  function discContent(){return `<div class="chart-shell" id="primary-chart">${svg('disc')}</div>${playback()}<div class="pair-info" id="pair-info" role="status">${selected()?`${selected().absolute_reach} reachable pairs in a ${selected().universe_size}-pair universe.`:'No credential selected.'}</div>${uncertainty()}<div class="view-subheading"><h3>Explanatory path</h3><button id="copy-narrative">${icon('copy')} Copy evidence narrative</button></div><div class="chart-shell">${svg('path')}</div><details><summary>Path narrative</summary><pre class="json">${esc(narrative())}</pre></details>${(selected()?.blocked??[]).length?`<details><summary>${selected().blocked.length} blocked transitions</summary>${selected().blocked.map(item=>`<p class="barrier"><button data-node="${esc(item.edge_id)}">${esc(item.reason)} / ${esc(item.edge_id)}</button></p>`).join('')}</details>`:''}`;}
  function miniDisc(value,labelText){const radius=31*Math.sqrt(value??0);return `<div class="mini-disc"><svg viewBox="0 0 70 70" role="img" aria-label="${esc(labelText+' '+V.percent(value))}"><circle cx="35" cy="35" r="31" fill="none" stroke="#aab7bd" stroke-dasharray="3 3"/><circle cx="35" cy="35" r="${radius.toFixed(3)}" fill="#dce7ed" stroke="#344b56"/></svg><span>${labelText} ${V.percent(value)}</span></div>`;}
  function counterCards(){return `<div class="cards">${(baseResult().recommendations??[]).slice(0,5).map(change=>`<article class="counter-card"><h3>${esc(change.name)}</h3><div class="mini-discs">${miniDisc(change.before_p95,'Before')}${miniDisc(change.after_p95,'After')}</div><p>Canonical p95 / ${change.absolute_pairs_removed} credential-pair exposures removed / ${change.evaluated_candidates} candidates evaluated.</p><button data-remove="${esc(change.binding_id)}">${icon('minus')} Preview removal</button></article>`).join('')||'<p class="notice">No ranked single-binding evaluations are supplied for this result.</p>'}</div>`;}
  function whatifContent(){const source=result(),bindings=baseResult().snapshot.nodes.filter(node=>node.kind==='binding');return `<div class="controls"><label for="binding-select">Binding<select id="binding-select">${bindings.map(node=>`<option value="${esc(node.id)}">${esc(names()[node.id]??node.name)}</option>`).join('')}</select></label><button id="remove-selected">${icon('minus')} Remove</button><button id="add-binding">${icon('plus')} Add binding</button><button id="reset-whatif">${icon('rotate-left')} Restore snapshot</button></div><p class="notice">Local counterfactual only. No platform change is executed. Deleting a deny can increase reach.</p><div class="chart-shell">${svg('whatif')}</div>${tenantDelta()}<div class="view-subheading"><h3>Five evaluated single changes</h3></div>${counterCards()}`;}
  function tenantDelta(){const before=(state.view==='models'?input.files[state.dataset.models.default]:(state.baseline??baseResult())).statistics.canonical_radius,after=result().statistics.canonical_radius;return `<table><caption>Canonical tenant statistics / after minus before</caption><thead><tr><th>Statistic</th><th>Before</th><th>After</th><th>Delta</th></tr></thead><tbody>${['max','p95','gini','share_above_threshold'].map(key=>`<tr><td>${esc(key)}</td><td>${before[key]==null?'undefined':before[key].toFixed(4)}</td><td>${after[key]==null?'undefined':after[key].toFixed(4)}</td><td>${after[key]==null?'undefined':(after[key]-before[key]).toFixed(4)}</td></tr>`).join('')}</tbody></table>`;}
  function privacyContent(){const payload=summary(),analysis=input.files[input.manifest.privacy_analysis];return `<div class="chart-shell">${svg('privacy')}</div><p class="notice"><strong>Not anonymous.</strong> The prior synthetic privacy experiment found ${analysis.exact_summary.unique_rows}/${analysis.tenants} exact summaries unique. This does not estimate real-company re-identification probability.</p><details open><summary>Exact local payload JSON</summary><pre class="json">${esc(JSON.stringify(payload,null,2))}</pre></details><div class="key-value"><section><h3>Payload</h3><p>Fixed structural counts and histogram; no names, IDs, paths, hashes or timestamps.</p></section><section><h3>Stays local</h3><p>Full snapshot, credentials metadata, paths, provenance, weights and result details. No network submission exists.</p></section></div>`;}
  function playgroundContent(){const fixture=state.fixture??input.manifest.fixtures[0];return `<div class="controls"><label for="fixture-select">Conformance preset<select id="fixture-select">${input.manifest.fixtures.map(item=>`<option value="${item.id}" ${item.id===fixture.id?'selected':''}>${item.id} / ${esc(item.title)}${item.valid?'':' / invalid'}</option>`).join('')}</select></label><button id="evaluate">${icon('play')} Evaluate</button><button data-edit="node" title="Add resource node">${icon('plus')} Node</button><button data-edit="edge" title="Add a grant edge">${icon('link')} Edge</button><button data-edit="constraint" title="Add device constraint">${icon('shield')} Constraint</button><button id="reset-playground" title="Reset edited graph">${icon('rotate-left')} Reset preset</button></div><p id="draft-status" class="notice" role="status">${drafts.has(fixture.id)?'Edited graph / unsaved':'Original preset'} / ${esc(state.model)}</p><div class="editor-grid"><div><label for="graph-editor">Graph JSON</label><textarea id="graph-editor" spellcheck="false">${esc(drafts.get(fixture.id)??JSON.stringify(input.files[fixture.graph],null,2))}</textarea><p id="editor-error" class="error" role="status"></p></div><div><h3>Preset derivation / ${fixture.id}</h3><p>${esc(fixture.derivation)}</p><p>${fixture.requirements.map(esc).join(', ')}</p><div id="playground-outcome">${selected()?`${selected().absolute_reach} / ${selected().universe_size} = ${V.percent(selected().canonical_radius)}`:'No valid result'}</div></div></div><div class="chart-shell">${svg('playground')}</div>`;}
  function incidentsContent(){const incident=state.incident??input.manifest.incidents[0];return `<select class="incident-select" id="incident-select" aria-label="Public incident reconstruction">${input.manifest.incidents.map(item=>`<option value="${item.id}" ${item.id===incident.id?'selected':''}>${esc(item.title)}</option>`).join('')}</select><p class="notice">${esc(incident.evidence.grade)}. Historical rank: <strong>not identifiable</strong>; the full preincident population is unavailable.</p><p>${esc(incident.evidence.narrative)}</p><label class="check"><input type="checkbox" id="incident-control" ${state.control?'checked':''}>Apply hypothetical ${esc(incident.evidence.control)} control</label><div class="chart-shell">${svg('incidents')}</div><div class="chart-shell">${svg('path')}</div><details open><summary>Assumptions ledger</summary><ol class="assumption-list">${incident.evidence.assumptions.map(value=>`<li>${esc(value)}</li>`).join('')}</ol><p>${esc(incident.evidence.boundary)}</p></details><details><summary>Public source evidence</summary>${incident.evidence.sources.map(source=>`<p><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.title)}</a> / ${esc(source.publisher)} / ${esc(source.date)}</p>`).join('')}</details>`;}
  function conformanceContent(){const reports=Object.entries(input.manifest.conformance_reports).map(([name,file])=>[name,input.files[file]]);return `<p class="notice">Saved public core reports. Passing a finite corpus is not certification, provider completeness, or independent authorship.</p><table><caption>Requirement-by-implementation results</caption><thead><tr><th>Requirement</th>${reports.map(([name])=>`<th>${name}</th>`).join('')}</tr></thead><tbody>${Array.from({length:32},(_,index)=>`BR-R${String(index+1).padStart(2,'0')}`).map(rule=>`<tr><td><button data-rule="${rule}">${rule}</button></td>${reports.map(([,report])=>`<td>${report.requirements[rule]==='pass'?'PASS':'Manual / not automated'}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
  function updateURL(){const params=new URLSearchParams({view:state.view,snapshot:result().snapshot_hash,model:state.view==='lesson'?'default':state.model,item:String(result().credentials.findIndex(record=>record.credential_id===selected()?.credential_id)),lens:state.nhi?'nhi':'all'});try{history.replaceState(null,'','#'+params);}catch{}}
