  function selectView(view){stop();if(state.view==='playground'&&state.fixture&&$('#graph-editor'))drafts.set(state.fixture.id,$('#graph-editor').value);state.view=view;if(view==='playground'&&!state.fixture){state.fixture=input.manifest.fixtures[0];state.incident=null;state.preview=null;}else if(view==='incidents'&&!state.incident){state.incident=input.manifest.incidents[0];state.fixture=null;state.preview=null;}else if(!['playground','incidents'].includes(view)&&(state.fixture||state.incident)){state.fixture=null;state.incident=null;state.control=false;state.preview=null;}state.step=null;render();}
  function stop(){clearInterval(timer);timer=null;state.playing=false;}
  function scrub(step){state.step=Math.max(0,Math.min(Math.max(0,...inspect().map(item=>item.rank[0])),step));$('#primary-chart').innerHTML=svg('disc');$('#step-range').value=state.step;$('#step-output').textContent=`Step ${state.step} of ${$('#step-range').max}`;announce(`${inspect().filter(item=>item.rank[0]<=state.step).length} pairs through step ${state.step}`);}
